#include <bits/stdc++.h>
using namespace std;

const int MAXN = 2521;

struct FlowGraph {
    struct Edge {
        int to, flow, cap, cost, orig;
    };

    int n, source, sink;
    vector<vector<int>> adj;
    vector<Edge> edges;

    FlowGraph(int n, int source, int sink) : n(n), source(source), sink(sink), adj(n) {}

    int add_edge(int a, int b, int cap, int cost) {
        int id = (int)edges.size();
        adj[a].push_back(id);
        edges.push_back({b, 0, cap, cost, cost});
        adj[b].push_back(id + 1);
        edges.push_back({a, 0, 0, -cost, -cost});
        return id;
    }

    void bellman_ford() {
        vector<int> dist(n, INT_MAX / 2);
        dist[source] = 0;

        for (int rep = 0; rep < n; ++rep) {
            bool changed = false;
            for (int id = 0; id < (int)edges.size(); ++id) {
                int v = edges[id ^ 1].to;
                int u = edges[id].to;
                if (edges[id].flow < edges[id].cap &&
                    dist[v] != INT_MAX / 2 &&
                    dist[u] > dist[v] + edges[id].cost) {
                    dist[u] = dist[v] + edges[id].cost;
                    changed = true;
                    assert(rep < n - 1);
                }
            }
            if (!changed) break;
        }

        for (int id = 0; id < (int)edges.size(); ++id) {
            int v = edges[id ^ 1].to;
            int u = edges[id].to;
            if (dist[v] < INT_MAX / 2 && dist[u] < INT_MAX / 2)
                edges[id].cost += dist[v] - dist[u];
        }
    }

    pair<int,int> dijkstra() {
        const int INF = INT_MAX / 2;
        vector<int> dist(n, INF), prev(n, -1), maxf(n, 0);
        set<pair<int,int>> q;

        dist[source] = 0;
        prev[source] = -2;
        maxf[source] = INT_MAX;
        q.insert(make_pair(0, source));

        while (!q.empty()) {
            int d = q.begin()->first;
            int v = q.begin()->second;
            q.erase(q.begin());

            if (d != dist[v]) continue;

            for (int id : adj[v]) {
                Edge &e = edges[id];
                if (e.flow < e.cap) {
                    int nd = d + e.cost;
                    if (nd < dist[e.to]) {
                        dist[e.to] = nd;
                        prev[e.to] = id;
                        maxf[e.to] = min(maxf[v], e.cap - e.flow);
                        q.insert(make_pair(nd, e.to));
                    }
                }
            }
        }

        int last = prev[sink];
        if (last == -1) return make_pair(0, 0);

        int extra = maxf[sink];
        int atcost = 0;

        for (int id = last; id != -2; id = prev[edges[id ^ 1].to]) {
            edges[id].flow += extra;
            edges[id ^ 1].flow -= extra;
            atcost += edges[id].orig;
        }

        for (int id = 0; id < (int)edges.size(); ++id) {
            int v = edges[id ^ 1].to;
            int u = edges[id].to;
            if (prev[v] != -1 && prev[u] != -1)
                edges[id].cost += dist[v] - dist[u];
        }

        return make_pair(extra, atcost);
    }

    pair<int,int> mfmc() {
        int flow = 0, cost = 0;

        if (any_of(edges.begin(), edges.end(), [](const Edge &e) {
            return e.flow > 0 && e.cost < 0;
        })) bellman_ford();

        while (true) {
            pair<int,int> r = dijkstra();
            if (r.first == 0) break;
            flow += r.first;
            cost += r.first * r.second;
        }

        return make_pair(flow, cost);
    }
};

int to[130][MAXN];
vector<int> e[MAXN];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, K, c, d;
    cin >> n >> m >> K >> c >> d;

    const int max_time = 120;
    vector<int> a(K);
    for (int i = 0; i < K; ++i) cin >> a[i];

    for (int i = 1; i <= n; ++i) e[i].clear();
    for (int i = 0; i < m; ++i) {
        int x, y;
        cin >> x >> y;
        e[x].push_back(y);
        e[y].push_back(x);
    }

    int nd = 0;
    for (int i = 0; i < max_time; ++i)
        for (int j = 1; j <= n; ++j)
            to[i][j] = nd++;

    int S = nd++;
    int T = nd++;
    FlowGraph fg(nd, S, T);

    for (int i = 0; i < K; ++i)
        fg.add_edge(S, to[0][a[i]], 1, 0);

    for (int i = 0; i < max_time; ++i)
        fg.add_edge(to[i][1], T, K, c * i);

    for (int i = 0; i < max_time - 1; ++i) {
        for (int j = 1; j <= n; ++j) {
            for (int nb : e[j]) {
                for (int z = 0; z <= 52; ++z)
                    fg.add_edge(to[i][j], to[i + 1][nb], 1, d * (2 * z + 1));
            }
            fg.add_edge(to[i][j], to[i + 1][j], K, 0);
        }
    }

    pair<int,int> ans = fg.mfmc();
    cout << ans.second << '\n';

    return 0;
}
